const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const files = ['food-data', 'audio', 'particles', 'api', 'game', 'main'];
const source = files.map(name => fs.readFileSync(path.join(root, 'js', `${name}.js`), 'utf8')
    .replace(/^import .*;\s*$/gm, '')
    .replace(/^export /gm, ''));
fs.writeFileSync(path.join(root, 'js/game-app.js'),
    '// Generated by node scripts/build.cjs. Keeps direct file:// play working.\n' +
    "(() => {\n'use strict';\n" + source.join('\n') + '\n})();\n');
console.log('Build completed: js/game-app.js generated successfully.');
